# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), проверено перебором"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_ЗПТ_887", r"$(x-y)(x+y)=45$, множители одной чётности: $1\cdot45$, $3\cdot15$, $5\cdot9$ — пары $(23;22)$, $(9;6)$, $(7;2)$ (проверка: $49-4=45$); в ключе не было пары $7$ и $2$",
  k=r"$23$ и $22$, или $9$ и $6$, или $7$ и $2$",
  dnew={0: (r"$9$ и $6$ или $23$ и $22$", r"Ученик разобрал разложения $45=1\cdot45$ и $45=3\cdot15$, но не рассмотрел $45=5\cdot9$, которое даёт пару $x=7$, $y=2$."),
        1: (r"$9$ и $6$", r"Указана только одна пара, хотя уравнение $(x-y)(x+y)=45$ имеет три решения в натуральных числах."),
        2: (r"$15$ и $0$", r"Число $0$ не является натуральным; пара $(15;0)$ даёт $225-0=225\ne45$ и вообще не удовлетворяет уравнению.")})
E("G9_TB_ЗПТ_900_в", r"$\frac{3}{y^{2}}=x^{2}-1$ должно быть целым: $y^{2}\mid3\Rightarrow y=\pm1$, тогда $x^{2}=4$, $x=\pm2$: четыре целых решения $(\pm2;\pm1)$ (проверка: $4-\frac31=1$); ключ «нет целых решений» неверен",
  k=r"$(2; 1),\ (2; -1),\ (-2; 1),\ (-2; -1)$",
  dnew={0: (r"нет целых решений", r"Ученик решил, что дробь $\frac{3}{y^{2}}$ не может быть целой и решений нет; но при $y=\pm1$ она равна $3$ и $x^{2}=4$."),
        1: (r"$(2; 1)$ и $(-2; 1)$", r"Ученик подставил $y=1$, получил $x=\pm2$, но забыл $y=-1$: $y$ входит в уравнение в квадрате, поэтому решений четыре."),
        2: (r"$(1; \sqrt{3})$ и $(-1; \sqrt{3})$", r"Ученик нашёл нецелые $y$; в целых числах нужно $y^{2}\mid3$, то есть $y=\pm1$.")})
